# MultiStrike Chart Models

class MultiStrikeQuery(BaseModel):
    """
    Request payload for multistrike snapshot charts (OI, Volume, etc.).

    Attributes:
        exchange (ExchangeEnum): Market exchange.
        asset (str): Underlying asset symbol (e.g. "NIFTY").
        expiries (List[str]): Expiry dates in YYYYMMDD format. Empty list for futures mode.
        minStrike (int): Lower strike bound (strike × 100). 0 for futures mode.
        maxStrike (int): Upper strike bound (strike × 100). 0 for futures mode.
        strikes (List[int]): Explicit strike list (each × 100). Empty list for futures mode.
        fields (List[str]): Fields to fetch (e.g. ["cumulative_oi"], ["cumulative_volume"]).
        time (Optional[str]): Snapshot time in "YYYY-MM-DDTHH:MM:SSZ" layout (UTC). Defaults to server current time when omitted.
    """
    exchange: ExchangeEnum
    asset: str
    expiries: List[str] = Field(default_factory=list)
    minStrike: int = 0
    maxStrike: int = 0
    strikes: List[int] = Field(default_factory=list)
    fields: List[str]
    time: Optional[str] = None


class MultiStrikeResponse(BaseModel):
    """
    Response for multistrike chart endpoints.

    The result is a deeply nested dict keyed as:
    result[exchange][asset][time][expiry][strike][field] = {"CE": int, "PE": int} or {"FUT": int}

    In futures mode the strike key is "0" and values are keyed by "FUT" instead of "CE"/"PE".

    Attributes:
        market_time (str): Server-reported snapshot time.
        message (str): Status message.
        result (Dict): Nested response data.
    """
    market_time: Optional[str] = None
    message: Optional[str] = None
    result: Optional[Dict[str, Any]] = None


