# Shared FinancialsDataResponse shape (cash flow, balance sheet, P&L)

class FinancialChildValue(BaseModel):
    """
    A sub-row inside a financial statement value entry.
    `value` is a scaled integer (int64) for currency rows or a plain float for
    ratio rows; may be null.
    """
    label: Optional[str] = None
    value: Optional[Any] = None
    is_key_ratio: Optional[bool] = None
